SET local check_function_bodies = off;

CREATE EXTENSION "pg_cron";

CREATE TABLE "public"."cities" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "province_id" bigint,
  "slug"        text,
  "title"       text,
  CONSTRAINT "cities_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."cities"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."discount_codes" (
  "id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "code"             text,
  "discount_percent" integer                  NOT NULL,
  "max_discount"     bigint,
  "min_purchase"     bigint                   NOT NULL,
  "expires_at"       timestamp with time zone,
  "is_active"        boolean                  NOT NULL,
  CONSTRAINT "discount_codes_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."discount_codes"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."order_items" (
  "id"            bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "order_id"      bigint,
  "product_id"    uuid,
  "variant_id"    uuid,
  "product_title" text,
  "image"         text,
  "size_title"    text,
  "color_title"   text,
  "discount"      integer,
  "quantity"      integer,
  CONSTRAINT "order_items_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."order_items"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."orders" (
  "id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "user_id"          uuid,
  "product_discount" bigint,
  "discount_code_id" bigint,
  "subtotal"         bigint,
  "discount_amount"  bigint,
  "total_price"      bigint,
  "status"           text,
  "recipient_name"   text,
  "recipient_phone"  text,
  "province"         text,
  "city"             text,
  "postal_code"      text,
  "address"          text,
  "shipping_cost"    bigint                   NOT NULL DEFAULT 150000,
  "plate"            text,
  "unit"             text,
  "pending_at"       timestamp with time zone,
  "order_number"     integer                  NOT NULL DEFAULT (floor(((random() * (90000000)::double precision) + (10000000)::double precision)))::integer,
  CONSTRAINT "orders_order_number_unique" UNIQUE (order_number),
  CONSTRAINT "orders_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."orders"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."product_comments" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "user_id"    uuid,
  "product_id" uuid,
  "images"     text[],
  "score"      integer,
  "comment"    text,
  CONSTRAINT "product_comments_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."product_comments"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."provinces" (
  "id"    bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."porvinces_id_seq") NOT NULL,
  "slug"  text,
  "title" text,
  CONSTRAINT "porvinces_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."provinces"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."user_cart" (
  "id"                 uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "user_id"            uuid,
  "product_id"         uuid,
  "product_variant_id" uuid,
  "quantity"           bigint,
  CONSTRAINT "user_cart_pkey" PRIMARY KEY (id),
  CONSTRAINT "user_cart_quantity_positive" CHECK ((quantity > 0)),
  CONSTRAINT "user_cart_user_variant_unique" UNIQUE (user_id, product_variant_id)
);

ALTER TABLE "public"."user_cart"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."user_favorites" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "user_id"    uuid,
  "product_id" uuid,
  CONSTRAINT "unique_user_product" UNIQUE (user_id, product_id),
  CONSTRAINT "user_favorites_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."user_favorites"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."product_variants"
  ADD COLUMN "discount" integer;

CREATE OR REPLACE FUNCTION public.create_order_from_cart (
  p_discount_code_id bigint DEFAULT NULL::bigint
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
    v_user_id uuid;
    v_order_id bigint;

    v_subtotal numeric := 0;
    v_product_discount numeric := 0;
    v_discount_amount numeric := 0;
    v_final_subtotal numeric := 0;

    v_discount_percent numeric := 0;
    v_max_discount numeric;
    v_min_purchase numeric := 0;
    v_total_price bigint := 0;
begin
    -- Current authenticated user
    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception 'User is not authenticated';
    end if;

    -- Lock cart rows
    perform id
    from public.user_cart
    where user_id = v_user_id
    for update;

    if not found then
        raise exception 'Cart is empty';
    end if;

    -- Calculate subtotal and product discounts
    select
        coalesce(sum(pv.price * uc.quantity), 0),
        coalesce(
            sum(
                pv.price *
                coalesce(pv.discount, 0) / 100.0 *
                uc.quantity
            ), 0
        )
    into
        v_subtotal,
        v_product_discount
    from public.user_cart uc
    join public.product_variants pv
        on pv.id = uc.product_variant_id
    where uc.user_id = v_user_id;

    v_final_subtotal := v_subtotal - v_product_discount;

    -- Validate discount code
    if p_discount_code_id is not null then

        select
            discount_percent,
            max_discount,
            min_purchase
        into
            v_discount_percent,
            v_max_discount,
            v_min_purchase
        from public.discount_codes
        where id = p_discount_code_id
          and is_active = true
          and (
              expires_at is null
              or expires_at > now()
          );

        if not found then
            raise exception 'Invalid or expired discount code';
        end if;

        if v_final_subtotal < v_min_purchase then
            raise exception 'Minimum purchase requirement not met';
        end if;

        v_discount_amount := (
            v_final_subtotal * v_discount_percent / 100.0
        );

        if v_max_discount is not null then
            v_discount_amount := least(
                v_discount_amount,
                v_max_discount
            );
        end if;
    end if;

    -- Create order
    insert into public.orders (
        user_id,
        product_discount,
        discount_code_id,
        subtotal,
        discount_amount,
        total_price,
        status
    )
    values (
        v_user_id,
        round(v_product_discount),
        p_discount_code_id,
        round(v_subtotal),
        round(v_discount_amount),
        round(v_final_subtotal - v_discount_amount),
        'pending'
    )
    returning id into v_order_id;

    -- Insert order items
    insert into public.order_items (
        order_id,
        product_id,
        variant_id,
        product_title,
        image,
        size_title,
        color_title,
        discount,
        quantity
    )
    select
        v_order_id,
        p.id,
        pv.id,
        p.title,
        p.images[1],
        s.title,
        c.title,
        coalesce(pv.discount, 0),
        uc.quantity
    from public.user_cart uc
    join public.products p
        on p.id = uc.product_id
    join public.product_variants pv
        on pv.id = uc.product_variant_id
    left join public.sizes s
        on s.id = pv.size_id
    left join public.colors c
        on c.id = pv.color_id
    where uc.user_id = v_user_id;

    -- Clear cart only after successful insertion
    delete from public.user_cart
    where user_id = v_user_id;

    return v_order_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
BEGIN
    INSERT INTO public.users (
        id,
        phone
    )
    VALUES (
        NEW.id,
        NEW.phone
    );

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_order_pending_at()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
begin
    if tg_op = 'INSERT' then
        if new.status = 'pending' then
            new.pending_at = now();
        end if;
    else
        if new.status = 'pending'
           and old.status is distinct from 'pending' then
            new.pending_at = now();

        elsif new.status is distinct from 'pending' then
            new.pending_at = null;
        end if;
    end if;

    return new;
end;
$function$;

