CREATE TRIGGER set_order_pending_at_trigger
  BEFORE INSERT OR UPDATE OF status ON public.orders
  FOR EACH ROW
  EXECUTE FUNCTION public.set_order_pending_at();

CREATE POLICY "Anyone can view categories" ON "public"."categories"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

CREATE POLICY "Everyone can see Cities" ON "public"."cities"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Anyone can view colors" ON "public"."colors"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

CREATE POLICY "Everyone can select discount codes" ON "public"."discount_codes"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Users can view their own order items" ON "public"."order_items"
  FOR SELECT
  TO PUBLIC
  USING ((EXISTS ( SELECT 1
   FROM public.orders
  WHERE ((orders.id = order_items.order_id) AND (orders.user_id = ( SELECT auth.uid() AS uid))))));

CREATE POLICY " Users only can select orders" ON "public"."orders"
  FOR SELECT
  TO "authenticated"
  USING ((user_id = auth.uid()));

CREATE POLICY "Users only can insert row" ON "public"."orders"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((user_id = auth.uid()));

CREATE POLICY "Users only can update orders rows" ON "public"."orders"
  FOR UPDATE
  TO "authenticated"
  USING ((user_id = auth.uid()))
  WITH CHECK ((user_id = auth.uid()));

CREATE POLICY "Everyone can see comments a product" ON "public"."product_comments"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Users can be insert comments" ON "public"."product_comments"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((user_id = auth.uid()));

CREATE POLICY "Users can create a comment for a product" ON "public"."product_comments"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));

CREATE POLICY "Everyone can see Provinces" ON "public"."provinces"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Anyone can view sizes" ON "public"."sizes"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

CREATE POLICY "Users can add items to their own cart" ON "public"."user_cart"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));

CREATE POLICY "Users can delete their own cart" ON "public"."user_cart"
  FOR DELETE
  TO "authenticated"
  USING ((( SELECT auth.uid() AS uid) = user_id));

CREATE POLICY "Users can update their own cart" ON "public"."user_cart"
  FOR UPDATE
  TO "authenticated"
  USING ((( SELECT auth.uid() AS uid) = user_id))
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));

CREATE POLICY "Users can view their own cart" ON "public"."user_cart"
  FOR SELECT
  TO "authenticated"
  USING ((( SELECT auth.uid() AS uid) = user_id));

CREATE POLICY "Users can delete their own favorites" ON "public"."user_favorites"
  FOR DELETE
  TO "authenticated"
  USING ((( SELECT auth.uid() AS uid) = user_id));

CREATE POLICY "Users can insert their own favorites" ON "public"."user_favorites"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));

CREATE POLICY "Users can view their own favorites" ON "public"."user_favorites"
  FOR SELECT
  TO "authenticated"
  USING ((( SELECT auth.uid() AS uid) = user_id));

